code.java:
class Solution {
    public String removeTrailingZeros(String num){
        int end=num.length()-1;
        while(num.charAt(end)=='0')end--;
        return num.substring(0,end+1);
    }
}

code.kotlin:
class Solution {
    fun removeTrailingZeros(num:String):String{
        var end=num.lastIndex;
        while(num[end]=='0')end--;
        return num.substring(0,end+1)
    }
}

